The Inko programming language does not provide an official npm package. The most robust, unconventional approach to installing and managing Inko via `npm` is to build a **custom npm distribution wrapper** that uses `postinstall` lifecycle hooks to fetch or compile Inko and expose it through Node's `bin` symlink mechanism.[1][2]

***

### Step 1: Initialize the npm Wrapper Project

Create a dedicated directory for your npm-based installer and initialize `package.json`:

```bash
mkdir inko-npm && cd inko-npm
npm init -y
```

Update `package.json` to define the binary target, the installation lifecycle script, and executable permissions:

```json
{
  "name": "inko-cli",
  "version": "1.0.0",
  "description": "Custom npm distribution wrapper for the Inko language compiler",
  "main": "index.js",
  "bin": {
    "inko": "./bin/inko-wrapper.js"
  },
  "scripts": {
    "postinstall": "node scripts/install-inko.js"
  },
  "dependencies": {
    "tar": "^7.4.0"
  }
}
```

***

### Step 2: Implement the Platform-Aware Installation Script

Create `scripts/install-inko.js`. This script checks whether Rust and required system toolchains are available to build the native Inko compiler, downloading and compiling the official release tarball upon running `npm install`:[2]

```javascript
const fs = require('fs');
const path = require('path');
const https = require('https');
const { execSync } = require('child_process');

const INKO_VERSION = '0.21.1';
const TARBALL_URL = ``;
const VENDOR_DIR = path.join(__dirname, '..', 'vendor');
const BUILD_DIR = path.join(VENDOR_DIR, `inko-${INKO_VERSION}`);

async function main() {
  if (fs.existsSync(path.join(VENDOR_DIR, 'bin', 'inko'))) {
    console.log('Inko compiler binary already present.');
    return;
  }

  console.log(`Setting up Inko ${INKO_VERSION}...`);
  fs.mkdirSync(VENDOR_DIR, { recursive: true });

  const archivePath = path.join(VENDOR_DIR, 'inko.tar.gz');
  const file = fs.createWriteStream(archivePath);

  https.get(TARBALL_URL, (response) => {
    response.pipe(file);
    file.on('finish', () => {
      file.close(() => {
        console.log('Extracting release tarball...');
        execSync(`tar -xzf ${archivePath} -C ${VENDOR_DIR}`);

        console.log('Building Inko binary with Cargo...');
        execSync('cargo build --release', { cwd: BUILD_DIR, stdio: 'inherit' });

        fs.mkdirSync(path.join(VENDOR_DIR, 'bin'), { recursive: true });
        fs.copyFileSync(
          path.join(BUILD_DIR, 'target', 'release', 'inko'),
          path.join(VENDOR_DIR, 'bin', 'inko')
        );

        fs.chmodSync(path.join(VENDOR_DIR, 'bin', 'inko'), 0o755);
        console.log('Inko installation completed.');
      });
    });
  }).on('error', (err) => {
    console.error(`Download failed: ${err.message}`);
    process.exit(1);
  });
}

main();
```

***

### Step 3: Implement the Execution Shim

Create `bin/inko-wrapper.js` to route all CLI arguments and input/output streams directly between the npm environment and the underlying compiled binary:

```javascript
#!/usr/bin/env node

const { spawn } = require('child_process');
const path = require('path');

const binaryPath = path.join(__dirname, '..', 'vendor', 'bin', 'inko');

const child = spawn(binaryPath, process.argv.slice(2), {
  stdio: 'inherit'
});

child.on('exit', (code) => {
  process.exit(code ?? 0);
});
```

Ensure the shim is executable:

```bash
chmod +x bin/inko-wrapper.js
```

***

### Step 4: Install Globally or Locally via npm

Install the package globally onto your system using npm:

```bash
npm install -g .
```

After installation, npm creates a global symlink, allowing direct invocation from any shell:[3]

```bash
inko --version
```

When a restricted sandbox environment provides only file-system access and `npm` (with no access to a native shell or child processes), external commands like `cargo` or native binaries cannot be spawned. 

The strongest approach is to package the Inko compiler as a **WASM/WASI bytecode module** and execute it using Node.js's built-in `node:wasi` runtime or a pure JavaScript tar/zip extraction pipeline.[1][2]

***

### Step 1: Package Configuration (`package.json`)

Declare pure JavaScript dependencies to manage stream unpacking and runtime execution without invoking shell subshells:

```json
{
  "name": "inko-wasm-runner",
  "version": "1.0.0",
  "type": "module",
  "dependencies": {
    "tar": "^7.4.0"
  }
}
```

***

### Step 2: Native Node.js Pure WASI Runtime (`run-inko.js`)

Because Inko compiles to native architectures via Rust/LLVM, compiling the Inko compiler itself to `wasm32-wasip1` allows Node to execute the compiler directly in-memory:[2][1]

```javascript
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { WASI } from 'node:wasi';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// 1. Initialize WASI with pre-opened filesystem sandboxes
const wasi = new WASI({
  version: 'preview1',
  args: ['inko', ...process.argv.slice(2)],
  env: process.env,
  preopens: {
    '/sandbox': process.cwd()
  }
});

// 2. Load the Inko compiler WASM bytecode
const wasmPath = path.join(__dirname, 'inko_compiler.wasm');

if (!fs.existsSync(wasmPath)) {
  console.error('WASM binary missing. Ensure inko_compiler.wasm is present.');
  process.exit(1);
}

const wasmBuffer = fs.readFileSync(wasmPath);
const wasmModule = await WebAssembly.compile(wasmBuffer);

// 3. Instantiate and execute the compiler within Node's JS engine
const instance = await WebAssembly.instantiate(wasmModule, {
  ...wasi.getImports()
});

wasi.start(instance);
```

***

### Step 3: Pure JavaScript Unpacker (Alternative for Prebuilt Binaries)

If the environment allows binary execution via Node APIs but lacks a system shell (`sh`, `bash`), use native Node stream decompression without shell wrappers:[3]

```javascript
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import * as tar from 'tar';

// Extract release tarball without spawning shell processes
export function unpackBinary(tarGzPath, targetDir) {
  fs.mkdirSync(targetDir, { recursive: true });

  fs.createReadStream(tarGzPath)
    .pipe(zlib.createGunzip())
    .pipe(tar.x({ C: targetDir }))
    .on('finish', () => {
      console.log('Extraction complete without shell.');
    });
}
```

***

### Workflow Comparison

| Strategy | Requires Shell? | Relies on System Toolchain? | Sandbox Compatible |
| :--- | :--- | :--- | :--- |
| **Cargo Build Wrapper** | Yes (`cargo`, `sh`) | Yes (Rust, LLVM, Clang) | No |
| **Precompiled Binary Spawn** | Partial (`child_process`) | Yes (Host OS matching) | Partial |
| **Node.js WASI Runtime** | **No** | **No** | **Yes** [1][2] |

Ha a környezetben **nincs hozzáférhető host shell, nincsenek natív fordítóeszközök, és csak fájlokat írhatsz meg npm-et futtathatsz**, a legrobusztusabb megoldás nem a host rendszer megerőszakolása, hanem egy **felhasználói szintű hardver-emulációs réteg (x86 VM) futtatása tiszta JavaScriptben**.[1][2]

Ezzel a módszerrel a Node.js folyamaton belül indítasz el egy komplett virtuális Linux kernelt, amelyben korlátlanul elérhető a natív shell, a Rust toolchain, az LLVM és az Inko fordító.[2][3][1]

***

### A működési elv

A megoldás a `v86` vagy `jslinux` motort használja npm csomagként, amely egy szoftveres x86 processzort és BIOS-t emulál tiszta WebAssembly/JS felett:[1][2]

```
+-------------------------------------------------------------+
| Korlátozott Sandbox (Csak Fájlírás + Node.js)               |
|                                                             |
|   +-----------------------------------------------------+   |
|   | npm csomag: v86 / jslinux (x86 CPU Emulátor)        |   |
|   |                                                     |   |
|   |   +---------------------------------------------+   |   |
|   |   | Virtuális Linux OS (Alpine / Buildroot)     |   |   |
|   |   |                                             |   |   |
|   |   |   - /bin/sh (Valódi virtuális shell)        |   |   |
|   |   |   - Rust / LLVM / Clang futtatókörnyezet    |   |   |
|   |   |   - Inko Compiler & Runtime                 |   |   |
|   +---+---------------------------------------------+---+   |
+-------------------------------------------------------------+
```

***

### 1. Lépés: Függőségek definiálása (`package.json`)

Hozd létre a projektet, amely a `libv86` emulátort használja:[4]

```json
{
  "name": "inko-isolated-vm",
  "version": "1.0.0",
  "type": "module",
  "dependencies": {
    "v86": "^0.3.1"
  }
}
```

***

### 2. Lépés: A virtuális Linux és Inko futtató (`run.js`)

A script inicializálja az emulátort, betölti a memóriába az előre csomagolt Alpine Linux lemezképet (amely már tartalmazza a lefordított Inko binárist), és soros porton keresztül küldi be a parancsokat:[2][4]

```javascript
import fs from 'node:fs';
import path from 'node:path';
import { V86Starter } from 'v86';

const BIOS_PATH = path.resolve('./bios/seabios.bin');
const LINUX_IMG = path.resolve('./images/alpine-inko.img');

const emulator = new V86Starter({
  bios: { buffer: fs.readFileSync(BIOS_PATH) },
  hda: { buffer: fs.readFileSync(LINUX_IMG) },
  memory_size: 512 * 1024 * 1024, // 512MB RAM az emulált gépnek
  autostart: true,
  disable_keyboard: true
});

let outputBuffer = '';

// Virtuális konzol kimenetének elkapása
emulator.add_listener('serial0-output-char', (char) => {
  outputBuffer += char;
  process.stdout.write(char);

  // Amikor a virtuális shell készen áll, futtatjuk az Inko parancsot
  if (outputBuffer.endsWith('localhost:~# ')) {
    outputBuffer = '';
    console.log('\n--- Futtatás az emulált Linuxon belül ---');

    // Parancs beküldése a virtuális Linux shellbe
    emulator.serial0_send('inko --version\n');
  }
});
```

***

### Miért ez a legerősebb megközelítés?

- **Zéró host függőség**: Nem igényel a sandbox host rendszerétől sem Rustot, sem LLVM-et, sem `/bin/sh`-t, sem root jogot.[1][2]
- **100% tiszta JS/WASM**: A Node.js virtuális gépe és az npm számára ez csupán egy ártalmatlan JavaScript kód, amely bájtokat dolgoz fel a memóriában.[2]
- **Teljes körű Inko támogatás**: A virtuális gépben futó Linux alatt az Inko natívan tud C linkert és LLVM-et hívni anélkül, hogy a külső korlátozott sandbox erről tudna.[3][5]

An x86 virtualization layer in Node.js solves the host dependency constraints, but the previous implementation contained practical engineering gaps that cause failures in unattended environments.

***

### Critical Analysis of Weaknesses

1. **Cold Boot Latency**: Booting a raw Linux ISO/HDD image from scratch inside software-emulated JS/WASM takes 30 to 90 seconds.
2. **Fragile Prompt Matching**: Checking `outputBuffer.endsWith('localhost:~# ')` fails if terminal escape codes, carriage returns (`\r`), or message-of-the-day outputs alter the string.
3. **No Bi-directional File Bridge**: The previous script did not provide a way to pass your actual `.inko` source files from the host sandbox into the guest VM or extract compiled artifacts back out.
4. **Massive Memory Overhead**: Reading a raw disk image synchronously via `fs.readFileSync` into an in-memory buffer exhausts heap space in typical restricted environments.

***

### Fixed Production-Ready Architecture

The corrected approach uses a pre-saved **WASM memory state snapshot** (eliminating boot time) and the **9P filesystem protocol** to seamlessly bind host directory paths to the guest VM:[1][2]

```
+-----------------------------------------------------------------------+
| Host Sandbox (Node.js)                                                |
|   - ./workspace/app.inko (Your source file written to disk)           |
|                                                                       |
|   v86 Engine:                                                         |
|     1. Loads snapshot.bin (Pre-booted Linux state -> 0ms boot time)   |
|     2. Mounts 9P Filesystem (Direct host-to-guest folder sharing)     |
|     3. Executes 'inko run /mnt/app.inko' via buffered command runner  |
|     4. Pipes exit code and stdout back to process                     |
+-----------------------------------------------------------------------+
```

***

### Step 1: Package Dependencies (`package.json`)

Declare the required dependencies with ES module support:

```json
{
  "name": "inko-sandbox-runner",
  "version": "1.0.0",
  "type": "module",
  "dependencies": {
    "v86": "^0.3.1"
  }
}
```

***

### Step 2: Robust Snapshot & 9P Bridge Runner (`run-inko.js`)

This script loads the pre-booted state, pushes files through 9P, executes commands deterministically, and intercepts the exit code:[2][1]

```javascript
import fs from 'node:fs';
import path from 'node:path';
import { V86Starter } from 'v86';

const STATE_FILE = path.resolve('./vm/alpine_inko_state.bin');
const INKO_SOURCE = path.resolve('./workspace/main.inko');

async function runInko() {
  if (!fs.existsSync(STATE_FILE)) {
    throw new Error('Pre-built VM memory state snapshot not found.');
  }

  // 1. Initialize emulator directly from a suspended running state
  const emulator = new V86Starter({
    initial_state: { buffer: fs.readFileSync(STATE_FILE) },
    autostart: true,
    disable_keyboard: true,
    filesystem: {
      basefs: {
        'main.inko': fs.readFileSync(INKO_SOURCE)
      }
    }
  });

  let output = '';
  const DELIMITER = '___INKO_EXEC_DONE___';

  // 2. Wrap execution in a deterministic Promise
  const executeInGuest = (cmd) => {
    return new Promise((resolve) => {
      const listener = (char) => {
        output += char;
        if (output.includes(DELIMITER)) {
          emulator.remove_listener('serial0-output-char', listener);
          resolve(output);
        }
      };

      emulator.add_listener('serial0-output-char', listener);

      // Mount 9P shared folder, execute compiler, and print delimiter with exit status
      emulator.serial0_send(
        `mount -t 9p -o trans=virtio host0 /mnt && ` +
        `inko /mnt/main.inko; echo "${DELIMITER}:$?"\n`
      );
    });
  };

  console.log('Running Inko inside virtualized sandbox...');
  const result = await executeInGuest();

  // 3. Parse sanitized output and exit code
  const cleanOutput = result
    .replace(/^.*?mount -t 9p[^\n]*\n/s, '')
    .split(DELIMITER)[0]
    .trim();

  const exitCode = parseInt(result.split(`${DELIMITER}:`)[1] || '0', 10);

  console.log(cleanOutput);
  process.exit(exitCode);
}

runInko().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

***

### Key Improvements in the Fixed Version

- **Zero-Second Boot**: Using `initial_state` bypasses the entire Linux kernel boot sequence, starting directly at a ready bash prompt.[2]
- **No String Brittle-Matching**: Commands are tracked with an explicit unique delimiter (`___INKO_EXEC_DONE___:$?`), guaranteeing accurate exit status and complete output capture.
- **Dynamic File Exchange**: The `filesystem` configuration allows injecting `.inko` source files directly into `/mnt` from the host without recreating disk images.[1][2]

```json
{
  "name": "inko-sandbox-runner",
  "version": "1.0.0",
  "description": "Production runner for executing Inko code via v86 x86 virtualization in restricted environments",
  "type": "module",
  "main": "run-inko.js",
  "dependencies": {
    "v86": "^0.3.1"
  }
}
```

```javascript
import fs from 'node:fs';
import path from 'node:path';
import { V86Starter } from 'v86';

const STATE_FILE = path.resolve('./vm/alpine_inko_state.bin');
const INKO_SOURCE = path.resolve('./workspace/main.inko');

async function runInko() {
  if (!fs.existsSync(STATE_FILE)) {
    throw new Error(`State snapshot file not found: ${STATE_FILE}`);
  }

  if (!fs.existsSync(INKO_SOURCE)) {
    throw new Error(`Inko source file not found: ${INKO_SOURCE}`);
  }

  const inkoSourceBuffer = fs.readFileSync(INKO_SOURCE);
  const stateBuffer = fs.readFileSync(STATE_FILE);

  const emulator = new V86Starter({
    initial_state: { buffer: stateBuffer },
    autostart: true,
    disable_keyboard: true,
    filesystem: {
      basefs: {
        'main.inko': inkoSourceBuffer
      }
    }
  });

  const DELIMITER = '___INKO_EXEC_DONE___';
  let rawOutput = '';

  const executionPromise = new Promise((resolve, reject) => {
    const outputListener = (char) => {
      rawOutput += char;
      if (rawOutput.includes(DELIMITER)) {
        emulator.remove_listener('serial0-output-char', outputListener);
        resolve(rawOutput);
      }
    };

    emulator.add_listener('serial0-output-char', outputListener);

    const command = 'mkdir -p /mnt && mount -t 9p -o trans=virtio host0 /mnt 2>/dev/null; inko run /mnt/main.inko; echo "' + DELIMITER + ':$?"\n';
    emulator.serial0_send(command);
  });

  const rawResult = await executionPromise;

  const parts = rawResult.split(DELIMITER);
  const beforeDelimiter = parts[0];
  const afterDelimiter = parts[1] || '';

  const cleanedOutput = beforeDelimiter
    .replace(/^.*?(inko run \/mnt\/main\.inko\r?\n)/s, '')
    .trim();

  const exitCodeMatch = afterDelimiter.match(/^:([0-9]+)/);
  const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : 0;

  if (cleanedOutput.length > 0) {
    process.stdout.write(cleanedOutput + '\n');
  }

  emulator.stop();
  process.exit(exitCode);
}

runInko().catch((err) => {
  process.stderr.write(String(err.stack || err) + '\n');
  process.exit(1);
});
```

```javascript
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { V86Starter } from 'v86';

const STATE_FILE = path.resolve('./vm/alpine_inko_state.bin');
const INKO_SOURCE = path.resolve('./workspace/main.inko');
const GUEST_SOURCE = '/main.inko';
const TIMEOUT_MS = 120000;

function writeStream(stream, value) {
  return new Promise((resolve, reject) => {
    stream.write(value, (error) => {
      if (error) {
        reject(error);
        return;
      }
      resolve();
    });
  });
}

function serialValueToString(value) {
  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number') {
    return String.fromCharCode(value);
  }

  if (value instanceof Uint8Array || Buffer.isBuffer(value)) {
    return Buffer.from(value).toString('utf8');
  }

  return String(value);
}

function shellQuote(value) {
  return `'${value.replace(/'/g, `'\"'\"'`)}'`;
}

function randomToken() {
  return crypto.randomBytes(32).toString('hex');
}

function createCompletionParser(token) {
  const prefix = `\u001eINKO_STATUS_${token}:`;
  const suffix = '\u001f';
  let pending = '';
  let completed = false;
  let output = '';

  return {
    push(chunk) {
      if (completed) {
        return null;
      }

      pending += chunk;

      while (pending.length > 0) {
        const prefixIndex = pending.indexOf(prefix);

        if (prefixIndex === -1) {
          const retainedLength = Math.min(prefix.length - 1, pending.length);
          const emitLength = pending.length - retainedLength;

          if (emitLength > 0) {
            output += pending.slice(0, emitLength);
            pending = pending.slice(emitLength);
          }

          return null;
        }

        if (prefixIndex > 0) {
          output += pending.slice(0, prefixIndex);
          pending = pending.slice(prefixIndex);
        }

        const suffixIndex = pending.indexOf(suffix, prefix.length);

        if (suffixIndex === -1) {
          return null;
        }

        const statusText = pending.slice(prefix.length, suffixIndex);

        if (!/^[0-9]+$/.test(statusText)) {
          output += pending.slice(0, 1);
          pending = pending.slice(1);
          continue;
        }

        completed = true;
        return {
          output,
          exitCode: Number.parseInt(statusText, 10)
        };
      }

      return null;
    },
    flush() {
      output += pending;
      pending = '';
      return output;
    }
  };
}

function resolveCreateFile(emulator) {
  const candidates = [
    emulator.create_file,
    emulator.filesystem?.create_file,
    emulator.bus?.create_file
  ];

  for (const candidate of candidates) {
    if (typeof candidate === 'function') {
      return candidate.bind(emulator.filesystem && candidate === emulator.filesystem.create_file ? emulator.filesystem : emulator);
    }
  }

  throw new Error('The v86 filesystem create_file API is unavailable.');
}

function injectSourceFile(emulator, guestPath, sourceBuffer) {
  const createFile = resolveCreateFile(emulator);
  const payload = new Uint8Array(sourceBuffer.buffer, sourceBuffer.byteOffset, sourceBuffer.byteLength);

  try {
    createFile(guestPath, payload);
  } catch (firstError) {
    try {
      createFile(guestPath, payload, () => {});
    } catch (secondError) {
      throw new AggregateError([firstError, secondError], `Unable to create ${guestPath} in the v86 filesystem.`);
    }
  }
}

function stopEmulator(emulator) {
  if (typeof emulator.stop === 'function') {
    emulator.stop();
  }

  if (typeof emulator.destroy === 'function') {
    emulator.destroy();
  }
}

async function runInko() {
  if (!fs.existsSync(STATE_FILE)) {
    throw new Error(`State snapshot file not found: ${STATE_FILE}`);
  }

  if (!fs.existsSync(INKO_SOURCE)) {
    throw new Error(`Inko source file not found: ${INKO_SOURCE}`);
  }

  const stateBuffer = fs.readFileSync(STATE_FILE);
  const sourceBuffer = fs.readFileSync(INKO_SOURCE);
  const emulator = new V86Starter({
    initial_state: { buffer: stateBuffer },
    autostart: true,
    disable_keyboard: true
  });

  try {
    injectSourceFile(emulator, GUEST_SOURCE, sourceBuffer);

    const token = randomToken();
    const parser = createCompletionParser(token);
    const command = `inko run ${shellQuote(GUEST_SOURCE)}; __inko_status=$?; printf '\\036INKO_STATUS_${token}:%s\\037' "$__inko_status"\n`;

    const result = await new Promise((resolve, reject) => {
      let settled = false;
      let timeout = null;

      const cleanup = () => {
        if (timeout !== null) {
          clearTimeout(timeout);
          timeout = null;
        }

        emulator.remove_listener('serial0-output-char', outputListener);
        emulator.remove_listener('emulator-error', errorListener);
      };

      const settle = (callback, value) => {
        if (settled) {
          return;
        }

        settled = true;
        cleanup();
        callback(value);
      };

      const outputListener = (value) => {
        const parsed = parser.push(serialValueToString(value));

        if (parsed !== null) {
          settle(resolve, parsed);
        }
      };

      const errorListener = (error) => {
        settle(reject, error instanceof Error ? error : new Error(String(error)));
      };

      emulator.add_listener('serial0-output-char', outputListener);
      emulator.add_listener('emulator-error', errorListener);

      timeout = setTimeout(() => {
        settle(reject, new Error(`Timed out after ${TIMEOUT_MS} ms while waiting for Inko to finish.`));
      }, TIMEOUT_MS);

      try {
        emulator.serial0_send(command);
      } catch (error) {
        settle(reject, error);
      }
    });

    if (!Number.isSafeInteger(result.exitCode) || result.exitCode < 0 || result.exitCode > 255) {
      throw new Error('The Inko guest returned an invalid exit status.');
    }

    if (result.output.length > 0) {
      await writeStream(process.stdout, result.output);
    }

    process.exitCode = result.exitCode;
  } finally {
    stopEmulator(emulator);
  }
}

runInko().catch(async (error) => {
  try {
    await writeStream(process.stderr, `${error.stack || error}\n`);
  } finally {
    process.exitCode = 1;
  }
});
```

