const GUEST_MOUNT_POINT = '/mnt/v86';
const HOST_FILESYSTEM_PATH = '/main.inko';
const GUEST_SOURCE = `${GUEST_MOUNT_POINT}/main.inko`;
const TIMEOUT_MS = 120000;

function writeStream(stream, value) {
  return new Promise((resolve, reject) => {
    stream.write(value, (error) => {
      if (error) {
        reject(error);
        return;
      }
      resolve();
    });
  });
}

function normalizeSerialText(value) {
  return value.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function shellQuote(value) {
  return `'${value.replace(/'/g, `'\"'\"'`)}'`;
}

function randomToken() {
  return crypto.randomBytes(32).toString('hex');
}

function buildCommand(token) {
  const stdoutFile = `/tmp/inko_stdout_${token}`;
  const stderrFile = `/tmp/inko_stderr_${token}`;

  return [
    `mkdir -p ${shellQuote(GUEST_MOUNT_POINT)} >/dev/null 2>&1`,
    `mount -t 9p -o trans=virtio,version=9p2000.L host9p ${shellQuote(GUEST_MOUNT_POINT)} >/dev/null 2>&1 || true`,
    `inko run ${shellQuote(GUEST_SOURCE)} > ${shellQuote(stdoutFile)} 2> ${shellQuote(stderrFile)}`,
    `__inko_status=$?`,
    `printf '\\036INKO_STDOUT_${token}\\037'`,
    `cat ${shellQuote(stdoutFile)}`,
    `printf '\\036INKO_STDERR_${token}\\037'`,
    `cat ${shellQuote(stderrFile)}`,
    `printf '\\036INKO_STATUS_${token}:%s\\037' "$__inko_status"`,
    `rm -f ${shellQuote(stdoutFile)} ${shellQuote(stderrFile)}`
  ].join('; ') + '\n';
}

function createCompletionParser(token) {
  const stdoutMarker = `\u001eINKO_STDOUT_${token}\u001f`;
  const stderrMarker = `\u001eINKO_STDERR_${token}\u001f`;
  const statusPrefix = `\u001eINKO_STATUS_${token}:`;
  const suffix = '\u001f';
  let pending = '';
  let state = 'discard';
  let stdoutText = '';
  let stderrText = '';
  let completed = false;

  const holdBack = (marker) => {
    const retainedLength = Math.min(marker.length - 1, pending.length);
    const emitLength = pending.length - retainedLength;

    if (emitLength <= 0) {
      return '';
    }

    const emitted = pending.slice(0, emitLength);
    pending = pending.slice(emitLength);
    return emitted;
  };

  return {
    push(chunk) {
      if (completed) {
        return null;
      }

      pending += chunk;

      while (pending.length > 0) {
        if (state === 'discard') {
          const markerIndex = pending.indexOf(stdoutMarker);

          if (markerIndex === -1) {
            holdBack(stdoutMarker);
            return null;
          }

          pending = pending.slice(markerIndex + stdoutMarker.length);
          state = 'stdout';
          continue;
        }

        if (state === 'stdout') {
          const markerIndex = pending.indexOf(stderrMarker);

          if (markerIndex === -1) {
            stdoutText += holdBack(stderrMarker);
            return null;
          }

          stdoutText += pending.slice(0, markerIndex);
          pending = pending.slice(markerIndex + stderrMarker.length);
          state = 'stderr';
          continue;
        }

        const prefixIndex = pending.indexOf(statusPrefix);

        if (prefixIndex === -1) {
          stderrText += holdBack(statusPrefix);
          return null;
        }

        if (prefixIndex > 0) {
          stderrText += pending.slice(0, prefixIndex);
          pending = pending.slice(prefixIndex);
        }

        const suffixIndex = pending.indexOf(suffix, statusPrefix.length);

        if (suffixIndex === -1) {
          return null;
        }

        const statusText = pending.slice(statusPrefix.length, suffixIndex);

        if (!/^[0-9]+$/.test(statusText)) {
          stderrText += pending.slice(0, 1);
          pending = pending.slice(1);
          continue;
        }

        completed = true;
        pending = '';
        return {
          stdoutText,
          stderrText,
          exitCode: Number.parseInt(statusText, 10)
        };
      }

      return null;
    },
    flush() {
      if (state === 'stderr') {
        stderrText += pending;
      } else {
        stdoutText += pending;
      }

      pending = '';
      return { stdoutText, stderrText };
    }
  };
}

async function injectSourceFile(emulator, guestPath, sourceBuffer) {
  if (typeof emulator.create_file !== 'function') {
    throw new Error('The v86 create_file API is unavailable.');
  }

  const payload = new Uint8Array(sourceBuffer.buffer, sourceBuffer.byteOffset, sourceBuffer.byteLength);
  await emulator.create_file(guestPath, payload);
}

function waitForEmulatorReady(emulator, timeoutMs) {
  return new Promise((resolve, reject) => {
    let timeout = null;

    const listener = () => {
      if (timeout !== null) {
        clearTimeout(timeout);
        timeout = null;
      }

      emulator.remove_listener('emulator-ready', listener);
      resolve();
    };

    emulator.add_listener('emulator-ready', listener);

    timeout = setTimeout(() => {
      emulator.remove_listener('emulator-ready', listener);
      reject(new Error(`Timed out after ${timeoutMs} ms while waiting for the emulator to become ready.`));
    }, timeoutMs);
  });
}

async function stopEmulator(emulator) {
  if (typeof emulator.stop === 'function') {
    try {
      await emulator.stop();
    } catch (stopError) {
      void stopError;
    }
  }

  if (typeof emulator.destroy === 'function') {
    try {
      await emulator.destroy();
    } catch (destroyError) {
      void destroyError;
    }
  }
}

async function runInko() {
  if (!fs.existsSync(STATE_FILE)) {
    throw new Error(`State snapshot file not found: ${STATE_FILE}`);
  }

  if (!fs.existsSync(INKO_SOURCE)) {
    throw new Error(`Inko source file not found: ${INKO_SOURCE}`);
  }

  if (!fs.existsSync(V86_WASM_PATH)) {
    throw new Error(`v86 wasm binary not found: ${V86_WASM_PATH}`);
  }

  const stateBuffer = fs.readFileSync(STATE_FILE);
  const sourceBuffer = fs.readFileSync(INKO_SOURCE);
  const stateArrayBuffer = stateBuffer.buffer.slice(stateBuffer.byteOffset, stateBuffer.byteOffset + stateBuffer.byteLength);

  const emulator = new V86({
    wasm_path: V86_WASM_PATH,
    initial_state: { buffer: stateArrayBuffer },
    filesystem: {},
    autostart: false,
    disable_keyboard: true
  });

  try {
    await waitForEmulatorReady(emulator, TIMEOUT_MS);
    await injectSourceFile(emulator, HOST_FILESYSTEM_PATH, sourceBuffer);
    await emulator.run();

    const token = randomToken();
    const parser = createCompletionParser(token);
    const command = buildCommand(token);
    const decoder = new TextDecoder('utf-8');

    const result = await new Promise((resolve, reject) => {
      let settled = false;
      let timeout = null;

      const cleanup = () => {
        if (timeout !== null) {
          clearTimeout(timeout);
          timeout = null;
        }

        emulator.remove_listener('serial0-output-byte', outputListener);
      };

      const flushPartialOutput = () => {
        const flushed = parser.flush();
        const partialStdout = normalizeSerialText(flushed.stdoutText);
        const partialStderr = normalizeSerialText(flushed.stderrText);

        if (partialStdout.length > 0) {
          process.stdout.write(partialStdout);
        }

        if (partialStderr.length > 0) {
          process.stderr.write(partialStderr);
        }
      };

      const settle = (callback, value) => {
        if (settled) {
          return;
        }

        settled = true;
        cleanup();

        if (callback === reject) {
          flushPartialOutput();
        }

        callback(value);
      };

      const outputListener = (byte) => {
        const chunk = decoder.decode(Uint8Array.of(byte), { stream: true });

        if (chunk.length === 0) {
          return;
        }

        const parsed = parser.push(chunk);

        if (parsed !== null) {
          settle(resolve, parsed);
        }
      };

      emulator.add_listener('serial0-output-byte', outputListener);

      timeout = setTimeout(() => {
        settle(reject, new Error(`Timed out after ${TIMEOUT_MS} ms while waiting for Inko to finish.`));
      }, TIMEOUT_MS);

      try {
        emulator.serial0_send(command);
      } catch (error) {
        settle(reject, error instanceof Error ? error : new Error(String(error)));
      }
    });

    if (!Number.isSafeInteger(result.exitCode) || result.exitCode < 0 || result.exitCode > 255) {
      throw new Error('The Inko guest returned an invalid exit status.');
    }

    const finalStdout = normalizeSerialText(result.stdoutText);
    const finalStderr = normalizeSerialText(result.stderrText);

    if (finalStdout.length > 0) {
      await writeStream(process.stdout, finalStdout);
    }

    if (finalStderr.length > 0) {
      await writeStream(process.stderr, finalStderr);
    }

    process.exitCode = result.exitCode;
  } finally {
    await stopEmulator(emulator);
  }
}

runInko().catch((error) => {
  const normalized = error instanceof Error ? error : new Error(String(error));

  try {
    process.stderr.write(`${normalized.stack || normalized.message || String(normalized)}\n`);
  } catch (writeError) {
    void writeError;
  }

  process.exitCode = 1;
});
